style.css:
@-webkit-keyframes bouncePhys {
    0% {
        transform: translateY(0px) scale(1) skewX(0deg);
    }
    28% {
        transform: translateY(-7px) scaleY(1.03) scaleX(0.99) skewX(0.5deg);
    }
    50% {
        transform: translateY(1px) scaleY(1) scaleX(1) skewX(0deg);
    }
    72% {
        transform: translateY(8px) scaleY(0.96) scaleX(1.02) skewX(-0.5deg);
    }
    100% {
        transform: translateY(0px) scale(1) skewX(0deg);
    }
}

@keyframes bouncePhys {
    0% {
        transform: translateY(0px) scale(1) skewX(0deg);
    }
    28% {
        transform: translateY(-7px) scaleY(1.03) scaleX(0.99) skewX(0.5deg);
    }
    50% {
        transform: translateY(1px) scaleY(1) scaleX(1) skewX(0deg);
    }
    72% {
        transform: translateY(8px) scaleY(0.96) scaleX(1.02) skewX(-0.5deg);
    }
    100% {
        transform: translateY(0px) scale(1) skewX(0deg);
    }
}

/* Применение темы к главной странице Google */
@-moz-document url-prefix("https://google.com"), url-prefix("https://google.ru") {
/* Скрываем стандартный встроенный логотип Google */
    .lnXffd, .k1zZkc, img[alt="Google"], .logo img {
        opacity: 0 !important;
        visibility: hidden !important;
    }

    /* Настройка и позиционирование нового широкоформатного арта */
    .k1zZkc, .X06fee, .logo, .NT0Y6 {
        /* Вставьте прямую ссылку на ваше сохраненное изображение вместо 'ВАША_ССЫЛКА_НА_КАРТИНКУ' */
        background: url('https://squarespace-cdn.com') no-repeat center center !important;
        background-size: contain !important;
        
        /* Пропорции 16:9 под интерфейс */
        width: 560px !important;
        height: 315px !important;
        
        margin: 0 auto !important;
        display: block !important;
        position: relative !important;
        z-index: 5 !important;
        
        /* Запуск мягкой упругой анимации */
        animation: bouncePhys 2.4s ease-in-out infinite !important;
        -webkit-animation: bouncePhys 2.4s ease-in-out infinite !important;
        transform-origin: bottom center !important;
    }

    /* Подгоняем поисковую строку, чтобы она не наезжала на буквы */
    .RNNXgb, .gLFyf, form[action="/search"] {
        margin-top: 5px !important;
        position: relative !important;
        z-index: 10 !important;
    }
}
